insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Penduduk','Master data penduduk adalah sumber administrasi Desa yang harus dijaga akurasi, riwayat perubahan, wilayah, status validasi, dan kewenangan akses. Integrasi RT/RW CONNECT atau GPFFE dilakukan hanya sesuai otoritas dan mapping data yang disetujui.','MODULE','APPROVED',1,now(),array['Penduduk','Data Desa','RT/RW CONNECT','GPFFE'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Penduduk');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Keluarga','Data keluarga menghubungkan anggota rumah tangga, alamat, wilayah, dan indikator sosial-ekonomi. AI dapat menganalisis agregat dan tren tetapi tidak boleh membuka data pribadi kepada pengguna tanpa kewenangan.','MODULE','APPROVED',1,now(),array['Keluarga','Data Desa','Privasi'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Keluarga');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Pemerintahan Desa','Modul pemerintahan mengelola Kepala Desa, perangkat, struktur organisasi, wilayah, agenda, BPD, LKD, LAD, dan kelembagaan. AI membantu administrasi dan analisis tetapi keputusan pemerintahan tetap manusia.','MODULE','APPROVED',1,now(),array['Pemerintahan Desa','Perangkat Desa','BPD'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Pemerintahan Desa');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Produk Hukum Desa','Kelola Peraturan Desa, Peraturan Kepala Desa, Keputusan, berita acara, naskah dinas, dan JDIH Desa dengan metadata, versi, status, dasar hukum, serta arsip. AI dapat membantu menemukan dasar hukum dan membuat draft.','MODULE','APPROVED',1,now(),array['Produk Hukum Desa','Dokumen','Arsip','AI Companion'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Produk Hukum Desa');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Pelayanan Publik','Pelayanan mengikuti katalog layanan, persyaratan, verifikasi, persetujuan, penerbitan, tracking dan penutupan. AI menjelaskan proses, memeriksa kelengkapan berdasarkan konfigurasi, dan membantu draft respons.','MODULE','APPROVED',1,now(),array['Pelayanan','Katalog Layanan','Permohonan','Surat'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Pelayanan Publik');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Keuangan Desa','Keuangan menghubungkan pendapatan, belanja, pembiayaan, APB Desa, perubahan, penjabaran, DPA, RAK, kas, bank, pajak, bukti transaksi, realisasi dan laporan. AI melakukan analisis, bukan persetujuan pembayaran.','MODULE','APPROVED',1,now(),array['Keuangan','APB Desa','Dana Desa'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Keuangan Desa');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Pembangunan Desa','Rantai perencanaan dan pembangunan: RPJM Desa, RKP Desa, Musyawarah, usulan, prioritas, program, anggaran, kegiatan, kontrak, progres, monitoring, bukti lapangan, dan evaluasi.','MODULE','APPROVED',1,now(),array['Pembangunan','RPJM Desa','RKP Desa','Musyawarah'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Pembangunan Desa');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Indeks Desa','Indeks Desa menggunakan enam dimensi: layanan dasar, sosial, ekonomi, lingkungan, aksesibilitas, dan tata kelola pemerintahan Desa. AI membantu membaca indikator, gap, tren dan prioritas intervensi.','MODULE','APPROVED',1,now(),array['Indeks Desa','Dashboard','Pembangunan'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Indeks Desa');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: SDGs Desa','AI menghubungkan 17 tujuan SDGs Desa dengan indikator, baseline, target, capaian, sumber data, periode, program, dan bukti. Analisis harus menyebut sumber dan periode data.','MODULE','APPROVED',1,now(),array['SDGs Desa','Data Desa','Pembangunan'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: SDGs Desa');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Bantuan dan Perlindungan Sosial','Kelola program bantuan, calon penerima, verifikasi, distribusi, monitoring dan riwayat. AI membantu analisis kelayakan berbasis aturan yang dikonfigurasi tetapi tidak menetapkan penerima secara final.','MODULE','APPROVED',1,now(),array['Bantuan','Perlindungan Sosial','Privasi'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Bantuan dan Perlindungan Sosial');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Aset Desa','Aset dicatat berdasarkan kategori, nilai, kondisi, lokasi, sumber, pemanfaatan, sewa, pemindahtanganan, penghapusan dan pemeriksaan fisik. AI menandai aset tanpa bukti atau pemeriksaan terbaru.','MODULE','APPROVED',1,now(),array['Aset Desa','Keuangan'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Aset Desa');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: BUM Desa dan Ekonomi Desa','Kelola BUM Desa, unit usaha, penyertaan modal, kinerja, UMKM, koperasi dan potensi ekonomi. AI dapat menganalisis kinerja dan risiko berdasarkan data yang tersedia.','MODULE','APPROVED',1,now(),array['BUM Desa','Ekonomi Desa','Koperasi'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: BUM Desa dan Ekonomi Desa');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Musyawarah dan Partisipasi','Alur partisipasi: usulan warga, verifikasi, prioritas, musyawarah, keputusan, program, anggaran, pelaksanaan dan tindak lanjut. AI membantu merangkum aspirasi dan menghubungkan keputusan dengan perencanaan.','MODULE','APPROVED',1,now(),array['Musyawarah Desa','Partisipasi','BPD'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Musyawarah dan Partisipasi');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Informasi Publik','Kelola daftar informasi publik, informasi berkala, setiap saat, serta mekanisme permohonan, respons dan keberatan. AI harus memisahkan informasi publik dari data pribadi dan informasi yang dikecualikan.','MODULE','APPROVED',1,now(),array['Informasi Publik','Pelayanan','Privasi'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Informasi Publik');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Arsip dan Dokumen','Kelola arsip aktif, inaktif, vital, klasifikasi, retensi, metadata, versi, integritas, pencarian dan digitalisasi. AI membantu klasifikasi dan pencarian tanpa mengubah arsip asli.','MODULE','APPROVED',1,now(),array['Arsip','Dokumen'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Arsip dan Dokumen');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Kepatuhan','Regulatory Center memetakan regulasi ke kewajiban, deadline, penanggung jawab, bukti, status, temuan dan tindak lanjut. AI harus mendeteksi perubahan regulasi dan menandai modul terdampak.','MODULE','APPROVED',1,now(),array['Kepatuhan','Regulatory Center','AI Companion'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Kepatuhan');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Privasi dan Keamanan','Gunakan least privilege, RLS, klasifikasi data, dasar pemrosesan, tujuan, akses, koreksi, permintaan data, log akses, berbagi data, insiden dan breach management. AI Privacy Guardian mencegah kebocoran.','MODULE','APPROVED',1,now(),array['Privasi','Keamanan','AI Companion'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Privasi dan Keamanan');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Integrasi RT/RW CONNECT dan GPFFE','Integrasi bukan sumber keputusan otomatis. Setiap pertukaran data harus memiliki mapping, kewenangan, status sinkronisasi, konflik, audit log dan batas akses. OpenSID hanya referensi/model, bukan runtime integration.','MODULE','APPROVED',1,now(),array['RT/RW CONNECT','GPFFE','Data Exchange'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Integrasi RT/RW CONNECT dan GPFFE');
insert into public.ai_knowledge_items(title,content,classification,status,version,approved_at,module_codes,metadata) select 'Module: Administrasi Sistem','Kelola pengguna, role, hak akses, organisasi, wilayah, template, workflow, audit log dan konfigurasi. AI harus tunduk pada identitas, organisasi, territory dan RLS sebelum mengambil data.','MODULE','APPROVED',1,now(),array['Administrasi Sistem','Keamanan','RBAC'],'{}'::jsonb where not exists(select 1 from public.ai_knowledge_items where title='Module: Administrasi Sistem');